package com.phoenix.business.web;import com.phoenix.business.domain.*;import com.phoenix.business.repository.*;import com.phoenix.business.service.AuditService;import com.phoenix.business.web.dto.AttendanceResponse;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.security.core.Authentication;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.time.*;
@RestController @RequestMapping("/api/attendance") @RequiredArgsConstructor public class AttendanceController {private final AttendanceRepository repo;private final MemberRepository members;private final UserRepository users;private final AuditService audit;@PostMapping("/check-in/{memberId}")@Transactional public AttendanceResponse in(@PathVariable Long memberId,Authentication auth){Member m=members.findById(memberId).orElseThrow();if(m.getStatus()!=Member.Status.ACTIVE||m.getExpiryDate()==null||m.getExpiryDate().isBefore(LocalDate.now()))throw new IllegalArgumentException("Only active, unexpired members may check in");if(repo.findFirstByMemberIdAndStatusOrderByCheckedInAtDesc(memberId,Attendance.Status.CHECKED_IN).isPresent())throw new IllegalArgumentException("Member already has an open check-in");Attendance a=new Attendance();a.setMember(m);a.setCheckedInAt(Instant.now());a.setRecordedBy(users.findByUsernameIgnoreCase(auth.getName()).orElseThrow());a=repo.save(a);audit.record("ATTENDANCE_CHECK_IN","ATTENDANCE",a.getId(),m.getMemberCode());return AttendanceResponse.from(a);}@PostMapping("/check-out/{memberId}")@Transactional public AttendanceResponse out(@PathVariable Long memberId){Attendance a=repo.findFirstByMemberIdAndStatusOrderByCheckedInAtDesc(memberId,Attendance.Status.CHECKED_IN).orElseThrow(()->new IllegalArgumentException("No open check-in"));a.setCheckedOutAt(Instant.now());a.setStatus(Attendance.Status.CHECKED_OUT);a=repo.save(a);audit.record("ATTENDANCE_CHECK_OUT","ATTENDANCE",a.getId(),a.getMember().getMemberCode());return AttendanceResponse.from(a);}@GetMapping public Page<AttendanceResponse> list(@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to,@RequestParam(required=false)Long memberId,@PageableDefault(size=20,sort="checkedInAt",direction=Sort.Direction.DESC)Pageable p){LocalDate a=from==null?LocalDate.now():from,b=to==null?a:to;return repo.filter(a.atStartOfDay(ZoneOffset.UTC).toInstant(),b.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant(),memberId,p).map(AttendanceResponse::from);}}
